  var readingSec=Math.round(wc/200*60*10)/10;
  var score=50;
  if(wc>=5&&wc<=12) score+=15; else if(wc<5) score-=10; else if(wc>15) score-=10;
  if(charsNoSpace>=20&&charsNoSpace<=60) score+=15; else if(charsNoSpace>80) score-=15;
  if(hasQ) score+=5; if(/\d/.test(text)) score+=5; if(upperRatio>0.5&&wc>3) score-=10;
  score=Math.max(0,Math.min(100,score));
  return {chars:chars, charsNoSpace:charsNoSpace, words:wc, readingSec:readingSec,
          upperRatio:Math.round(upperRatio*100)/100, hasQuestion:hasQ, hasExclaim:hasEx, score:score}; }
